/** The imagery that drifts behind the map.
 *
 * WHAT SHIPS HERE IS A PLACEHOLDER. public/memorial/*.webp are generated by
 * scripts/prepare-memorial.mjs: aged emulsion, paper tone, grain and scratches,
 * depicting nobody and nothing. A memorial must not invent its own evidence, so
 * no synthesised photograph of a real person, place or event is used.
 *
 * TO USE REAL IMAGES
 *   1. Put the files in public/memorial/ (WebP or JPEG, around 1200px wide is
 *      plenty: the layer is blurred and dimmed).
 *   2. Replace the entries below. Keep the list between about 6 and 12 plates;
 *      the strip is duplicated once to loop seamlessly, so more plates means a
 *      longer cycle and more memory.
 *   3. Fill in `credit` for every image. Credits are rendered into the
 *      "Map notes & credits" panel in the footer.
 *   4. Clear only licensed, sourced material, and record the rights with your
 *      historical reviewers before publishing.
 *
 * The drift speed lives in CSS: --memorial-cycle in src/style.css. */
export const memorial = [
  { src: "/memorial/plate-01.webp", credit: "Placeholder plate 01" },
  { src: "/memorial/plate-02.webp", credit: "Placeholder plate 02" },
  { src: "/memorial/plate-03.webp", credit: "Placeholder plate 03" },
  { src: "/memorial/plate-04.webp", credit: "Placeholder plate 04" },
  { src: "/memorial/plate-05.webp", credit: "Placeholder plate 05" },
  { src: "/memorial/plate-06.webp", credit: "Placeholder plate 06" },
  { src: "/memorial/plate-07.webp", credit: "Placeholder plate 07" },
  { src: "/memorial/plate-08.webp", credit: "Placeholder plate 08" },
];

/** True while nothing but generated stand-ins are loaded, which the credits
 * panel says out loud so a placeholder is never mistaken for a record. */
export const memorialIsPlaceholder = memorial.every((m) =>
  /\/plate-\d+\.webp$/.test(m.src),
);
